globalThis.fee = 1;

function total(price) {
  const fee = 5;

  return [
    eval("price + fee"),
    (0, eval)("typeof price"),
    new Function("price", "return price + fee;")(price),
    eval?.("fee"),
  ];
}

console.log(total(10).join(","));
